Object.assign(SNIP,{"l50cu": "#include <atomic>\natomic<int> dem(0);          // biến đếm nguyên tử\nvoid tang() {\n    for (int i = 0; i < 1000; i++) dem++;   // ++ là MỘT thao tác không chia cắt được\n}\ndem += 5;                    // cũng nguyên tử\nint cu = dem.fetch_add(2);   // cộng 2, trả về giá trị TRƯỚC khi cộng\ndem.store(0);                // ghi\nint x = dem.load();          // đọc (viết dem cũng được)"});PRESET_NOTES["l50"]={"Ví dụ: atomic sửa tranh chấp": "Cùng chương trình như ví dụ tranh chấp ở Bài 49, chỉ đổi int thành atomic<int>. Mỗi dem++ chạy trọn trong một bước, không có ô cam nào trên dòng thời gian, và kết quả luôn là 20.", "So sánh: int thường và atomic": "Hai biến được tăng cùng số lần. Biến int bị mất lần tăng (ô cam: đọc rồi bị chen ngang), biến atomic thì đủ 16.", "Ví dụ: fetch_add cấp số thứ tự": "fetch_add(1) trả về giá trị cũ rồi tăng, như một máy cấp số: không hai luồng nào nhận trùng số. Luồng nào nhận số nào thì tùy thứ tự chạy, nhưng tập các số luôn là {1, 2, 3, 4}.", "Ví dụ: cờ atomic<bool>": "main lặp kiểm tra cờ xong (chờ bận) tới khi luồng tính xong. Với bool thường, trình biên dịch có thể coi giá trị không đổi và lặp mãi; atomic bảo đảm main thấy được lần ghi của luồng kia. Trong thực tế nên dùng join hoặc future (Bài 51) thay cho chờ bận.", "Lỗi: chép một atomic": "atomic không chép được (hàm tạo sao chép bị xóa). Muốn lấy giá trị: atomic<int> b(a.load()); hoặc int x = a;"};EX_HINTS["l50"]=[["Chỉ cần đổi int demChan = 0; thành atomic<int> demChan(0);", "Lambda bắt demChan theo tham chiếu."], ["Đoạn của luồng i: từ i·n/k + 1 tới (i+1)·n/k.", "tong += x trên atomic là nguyên tử."], ["fetch_add(1) trả về số trước khi tăng, nên các số cấp ra là 100, 101, … không trùng.", "Thứ tự luồng nhận số thay đổi mỗi lần chạy, nhưng min, max, tổng thì không."]];
/* ===================== BÀI 50 · atomic ===================== */
/* Bài 50 · atomic
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P50=[{label:"Ví dụ: atomic sửa tranh chấp",input:"",code:"#include <iostream>\n#include <thread>\n#include <atomic>\nusing namespace std;\n\natomic<int> dem(0);\nvoid tang(int n) {\n    for (int i = 0; i < n; i++) {\n        dem++;\n    }\n}\nint main() {\n    thread a(tang, 10);\n    thread b(tang, 10);\n    a.join();\n    b.join();\n    cout << \"dem = \" << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"},{type:"vars",names:["dem"]}]},{label:"So sánh: int thường và atomic",input:"",code:"#include <iostream>\n#include <thread>\n#include <atomic>\nusing namespace std;\n\nint thuong = 0;\natomic<int> nguyenTu(0);\nvoid tang(int n) {\n    for (int i = 0; i < n; i++) {\n        thuong++;\n        nguyenTu++;\n    }\n}\nint main() {\n    thread a(tang, 8);\n    thread b(tang, 8);\n    a.join();\n    b.join();\n    cout << \"int thuong: \" << thuong << \"\\n\";\n    cout << \"atomic: \" << nguyenTu << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"},{type:"vars",names:["thuong","nguyenTu"]}]},{label:"Ví dụ: fetch_add cấp số thứ tự",input:"",code:"#include <iostream>\n#include <thread>\n#include <atomic>\n#include <vector>\nusing namespace std;\n\natomic<int> soKe(1);\nint main() {\n    vector<int> ve(4);\n    vector<thread> ds;\n    for (int i = 0; i < 4; i++) {\n        ds.emplace_back([i, &ve]() {\n            ve[i] = soKe.fetch_add(1);\n        });\n    }\n    for (auto& t : ds) t.join();\n    int tong = 0;\n    for (int x : ve) tong += x;\n    cout << \"Tong cac so ve: \" << tong << \" (luon la 1+2+3+4)\\n\";\n    cout << \"So tiep theo: \" << soKe.load() << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"},{type:"vars",names:["soKe"]}]},{label:"Ví dụ: cờ atomic<bool>",input:"",code:"#include <iostream>\n#include <thread>\n#include <atomic>\nusing namespace std;\n\natomic<bool> xong(false);\natomic<long long> ketQua(0);\nvoid tinh() {\n    long long s = 0;\n    for (int i = 1; i <= 10; i++) s += i * i;\n    ketQua.store(s);\n    xong.store(true);\n}\nint main() {\n    thread t(tinh);\n    int cho = 0;\n    while (!xong.load()) {\n        cho++;\n    }\n    cout << \"Ket qua: \" << ketQua.load() << \"\\n\";\n    t.join();\n    return 0;\n}",viz:[{type:"threads"},{type:"vars",names:["xong","ketQua"]}]},{label:"Lỗi: chép một atomic",input:"",code:"#include <iostream>\n#include <atomic>\nusing namespace std;\n\nint main() {\n    atomic<int> a(5);\n    atomic<int> b = a;\n    cout << b << \"\\n\";\n    return 0;\n}"}];
const sim50=makeSim2(document.getElementById("sim-l50"),{id:"s50",presets:P50});
makeEx2(document.getElementById("ex-l50"),sim50,[{t:"Đếm số chẵn song song",d:"Nhập n và n số, rồi k (1 ≤ k ≤ 4). Chia dãy thành k đoạn liên tiếp (đoạn i từ chỉ số i·n/k tới (i+1)·n/k − 1), mỗi luồng đếm số chẵn trong đoạn của mình và cộng thẳng vào một <code>atomic&lt;int&gt;<\/code> dùng chung (mỗi lần gặp số chẵn tăng 1). In tổng số chẵn.",tests:[{in:"6\n1 2 3 4 5 6\n2",out:"3"},{in:"5\n2 4 6 8 10\n3",out:"5"},{in:"1\n7\n1",out:"0"}],start:"#include <iostream>\n#include <thread>\n#include <atomic>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (int& x : a) cin >> x;\n    int k;\n    cin >> k;\n    int demChan = 0;   // đổi thành atomic<int>\n    vector<thread> ds;\n    for (int i = 0; i < k; i++) {\n        ds.emplace_back([i, n, k, &a, &demChan]() {\n            for (int j = i * n / k; j < (i + 1) * n / k; j++)\n                if (a[j] % 2 == 0) demChan++;\n        });\n    }\n    for (auto& t : ds) t.join();\n    cout << demChan << \"\\n\";\n    return 0;\n}",need:/atomic\s*<\s*int\s*>/,needMsg:"Hãy dùng atomic<int>."},{t:"Tổng bội số của 3 hoặc 5",d:"Nhập n (1 ≤ n ≤ 300) và k (1 ≤ k ≤ 3). Tính tổng các số từ 1 tới n chia hết cho 3 hoặc 5, chia đoạn [1, n] cho k luồng, mọi luồng cộng vào một <code>atomic&lt;long long&gt;<\/code> bằng <code>+=<\/code> hoặc <code>fetch_add<\/code>. In tổng.",tests:[{in:"10 2",out:"33"},{in:"15 3",out:"60"},{in:"1 1",out:"0"}],start:"#include <iostream>\n#include <thread>\n#include <atomic>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    // atomic<long long> tong(0);\n    vector<thread> ds;\n    // ...\n    for (auto& t : ds) t.join();\n    return 0;\n}",need:/atomic\s*<\s*long\s+long\s*>/,needMsg:"Hãy dùng atomic<long long>."},{t:"Máy cấp số",d:"Nhập k (1 ≤ k ≤ 5). Tạo k luồng; mỗi luồng lấy một số thứ tự từ <code>atomic&lt;int&gt; so(100)<\/code> bằng <code>fetch_add(1)<\/code> và ghi vào <code>ve[i]<\/code>. Sau khi join, in số nhỏ nhất, số lớn nhất và tổng các số đã cấp, mỗi số một dòng, rồi dòng cuối in giá trị hiện tại của <code>so<\/code>.",tests:[{in:"3",out:"100\n102\n303\n103"},{in:"1",out:"100\n100\n100\n101"},{in:"5",out:"100\n104\n510\n105"}],start:"#include <iostream>\n#include <thread>\n#include <atomic>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int k;\n    cin >> k;\n    atomic<int> so(100);\n    vector<int> ve(k);\n    vector<thread> ds;\n    // mỗi luồng: ve[i] = so.fetch_add(1);\n    for (auto& t : ds) t.join();\n    return 0;\n}",need:/fetch_add\s*\(/,needMsg:"Hãy cấp số bằng fetch_add."}]);

makeQuiz("quiz50","score50",[{"q": "Vì sao <code>dem++<\/code> trên <code>atomic&lt;int&gt;<\/code> không bị mất lần tăng?", "o": ["Vì atomic chạy chậm hơn", "Vì đọc, cộng, ghi được làm trong một thao tác không thể chen ngang", "Vì atomic tự khóa mutex", "Vì chỉ một luồng được dùng atomic"], "a": 1, "e": "Phần cứng có lệnh tăng nguyên tử; không luồng nào chen được vào giữa."}, {"q": "<code>atomic&lt;int&gt; a(5); int x = a.fetch_add(3);<\/code> Khi đó x và a là:", "o": ["8 và 8", "5 và 8", "5 và 5", "3 và 8"], "a": 1, "e": "fetch_add trả về giá trị cũ (5) rồi cộng: a thành 8."}, {"q": "Câu lệnh nào trên atomic<int> a KHÔNG nguyên tử?", "o": ["a++", "a += 2", "a = a + 1", "a.fetch_add(1)"], "a": 2, "e": "a = a + 1 gồm một lần đọc a và một lần ghi riêng biệt."}, {"q": "Chuyển tiền giữa hai tài khoản (trừ A, cộng B) chạy ở nhiều luồng. Nên dùng:", "o": ["Hai biến atomic", "Một mutex khóa quanh cả hai thao tác", "Không cần gì", "volatile"], "a": 1, "e": "Hai thao tác phải đi cùng nhau; atomic chỉ bảo vệ từng thao tác riêng lẻ."}]);

